import{c as t,Q as s,j as n,m as o}from"./chunks/framework.BqPkuuVc.js";const p=JSON.parse('{"title":"TV screens","description":"","frontmatter":{},"headers":[],"relativePath":"user/screens/tv-screens.md","filePath":"user/screens/tv-screens.md"}'),a={name:"user/screens/tv-screens.md"};function r(i,e,l,c,d,h){return s(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="tv-screens" tabindex="-1">TV screens <a class="header-anchor" href="#tv-screens" aria-label="Permalink to &quot;TV screens&quot;">​</a></h1><p><strong>Audience:</strong> Event organisers setting up multi-TV displays at the finish area.</p><p>When you&#39;re driving several TVs at the arena, <strong>TV screens</strong> let you create and manage them as a group instead of one at a time. Manager can generate a screen per TV, split your classes across them automatically, and let you change the look of every TV in one go.</p><p>TV screens are ordinary <a href="./creating-screens">screens</a> named <code>tv1</code>, <code>tv2</code>, … — the name is the whole of what makes them a group. The tools on this page build and edit <strong>Leaderboard</strong> screens only, so a TV you switch to <strong>Start times</strong>, <strong>Live top 10</strong>, <strong>Time behind Superman</strong> or <strong>Position bump</strong> drops out of both and is configured on its own row like any other screen. It keeps its <code>tv</code> name, and the wizard will not hand that name out again.</p><h2 id="creating-a-set-of-tv-screens" tabindex="-1">Creating a set of TV screens <a class="header-anchor" href="#creating-a-set-of-tv-screens" aria-label="Permalink to &quot;Creating a set of TV screens&quot;">​</a></h2><p>On the <strong>Screens</strong> page, click <strong>Leaderboard classes</strong>.</p><p><strong>The first time</strong>, the dialog has two steps.</p><p><strong>Step 1 — how many, and the default look.</strong> Set the <strong>Number of TVs</strong>, then set the <strong>Default settings for all TV screens</strong> — Font Size, Number of Columns, Club Display, Time Display, and the Show Club Icons / Auto Scroll / Show Header switches. These defaults apply to every TV you create here; you can still adjust an individual TV afterwards. Click <strong>Next: Distribute Classes</strong>.</p><p><strong>Step 2 — split the classes across the TVs.</strong> Manager lays out one column per TV (each headed <code>tv1</code>, <code>tv2</code>, … with its competitor count) plus an <strong>Unassigned</strong> area. To arrange them:</p><ul><li><strong>Auto Distribute</strong> balances the classes across the TVs by competitor count, keeping age groups together — a good starting point.</li><li><strong>Drag</strong> class chips between TVs (or into <strong>Unassigned</strong>) to fine-tune.</li><li><strong>Add TV</strong> adds another screen; <strong>Unassign All</strong> clears everything to start over.</li></ul><p>Click <strong>Create TV screens</strong> to finish. Each TV becomes a screen you can open and monitor like any other.</p><p><strong>Afterwards</strong>, reopening <strong>Leaderboard classes</strong> goes straight to the class distribution — there&#39;s no step 1, because the TVs already exist and have their own settings. The button at the end reads <strong>Update</strong> instead. <strong>Add TV</strong> still adds one, and any TV added this way is given the next free <code>tv</code> number, skipping any already in use — including one you&#39;ve switched to Start times, which keeps its name even though it&#39;s no longer part of the distribution.</p><h2 id="opening-each-screen-on-its-tv" tabindex="-1">Opening each screen on its TV <a class="header-anchor" href="#opening-each-screen-on-its-tv" aria-label="Permalink to &quot;Opening each screen on its TV&quot;">​</a></h2><p>Each screen is a web page at a URL of the form:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http://&lt;server-address&gt;/screen/&lt;screen-id&gt;?eventId=&lt;event-id&gt;</span></span></code></pre></div><p>So <code>tv1</code> for an event is <code>http://&lt;server-address&gt;/screen/tv1?eventId=&lt;event-id&gt;</code>. The simplest way to get there:</p><ul><li><strong>On the server machine</strong>, click the screen&#39;s <strong>ID link</strong> on the Screens page — it opens the screen in a new browser tab.</li><li><strong>On another device</strong> (a smart TV, a media stick, a laptop driving an HDMI output), open that device&#39;s browser and go to the URL above, substituting your server&#39;s address. Copy the link from the open tab&#39;s address bar if it&#39;s easier than typing.</li></ul><blockquote><p>Older links of the form <code>…/leaderboard/&lt;screen-id&gt;?eventId=…</code> still work, and they show whatever that screen is now set to — so televisions already pointed at one don&#39;t need touching. New links use <code>/screen/</code>.</p></blockquote><p>Put the browser <strong>full-screen</strong> (press <code>F11</code> on most desktop browsers) for a clean display, and turn off <strong>Show Header</strong> in the screen&#39;s settings if you want to reclaim the top strip. There&#39;s no separate software or kiosk component to install — a browser pointed at the URL is all each TV needs.</p><h3 id="driving-several-tvs-from-one-computer" tabindex="-1">Driving several TVs from one computer <a class="header-anchor" href="#driving-several-tvs-from-one-computer" aria-label="Permalink to &quot;Driving several TVs from one computer&quot;">​</a></h3><p>You don&#39;t need a computer per TV. Open each screen in its <strong>own browser window</strong>, then drag each window onto a different monitor or HDMI output and full-screen it there. One PC with several outputs can drive several TVs this way, each showing a different screen.</p><h2 id="changing-all-the-tvs-at-once" tabindex="-1">Changing all the TVs at once <a class="header-anchor" href="#changing-all-the-tvs-at-once" aria-label="Permalink to &quot;Changing all the TVs at once&quot;">​</a></h2><p>Two controls act on the whole group:</p><ul><li><strong>Edit all Leaderboards</strong> opens a settings dialog that applies to <strong>every Leaderboard TV screen</strong>. It covers the Leaderboard layout settings plus <strong>Theme</strong> and <strong>Language</strong>, so you can take every TV in the hall to Dark in one go. Only the settings you actually change are pushed out — anything you leave alone is untouched, and a setting that currently differs between TVs shows as <strong>[Mixed]</strong> until you set it. A TV showing start times is left alone, since the rest are Leaderboard settings; the button disappears entirely if none of your TVs is a Leaderboard.</li><li>The <strong>refresh</strong> button on a screen&#39;s row (<strong>Force reload TV screen</strong>) reloads that display remotely — handy if a browser has got stuck without you walking over to it.</li></ul><p>To re-balance which classes show on which TV later, reopen the dialog with <strong>Leaderboard classes</strong>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./creating-screens">Creating screens</a> — choosing what a screen shows, its settings and its health</li><li><a href="./commentary">Commentary</a> — the announcer&#39;s live feed</li></ul>',27)])])}const u=t(a,[["render",r]]);export{p as __pageData,u as default};
